(function(root){
'use strict';
const CASES=[
 {id:'functional',title:'Functional smoke test',guidance:'Define a representative user transaction, expected response and side effects. Use non-production test data.'},
 {id:'image-pull',title:'Image pull & startup',guidance:'Record actual digest, target registry pull, startup/readiness and restart behavior. Preflight alone does not verify a pull.'},
 {id:'connectivity',title:'Dependency & route behavior',guidance:'List required DNS/TLS and dependency paths, expected responses and an unauthorized path that must fail. Link security workbench evidence.'},
 {id:'observability',title:'Logs, metrics & alerts',guidance:'Trigger a controlled test event; verify logs, metrics, traces where applicable and actionable alert delivery.'},
 {id:'performance',title:'Load & scaling',guidance:'Specify workload, duration, concurrency, latency/error thresholds and scaling expectations; record comparable measurements.'},
 {id:'recovery',title:'Recovery rehearsal',guidance:'Define an approved disruption, recovery target and integrity checks. Reconcile target writes before failback; link the stateful plan where relevant.'}
];
const text=(v,name,max=8000)=>{if(typeof v!=='string'||v.length>max)throw Error('Invalid acceptance '+name+'.');return v.trim();};
function object(v,name){if(!v||typeof v!=='object'||Array.isArray(v))throw Error('Invalid acceptance '+name+'.');return v;}
function settings(input={}){object(input,'settings');const out={sourceContext:text(input.sourceContext??'','source context',300),targetContext:text(input.targetContext??'','target context',300),cases:{}};if(/[\r\n]/.test(out.sourceContext+out.targetContext))throw Error('Acceptance contexts must be single-line names.');const records=object(input.cases??{},'cases');for(const id of Object.keys(records))if(!CASES.some(c=>c.id===id))throw Error('Unknown acceptance case.');for(const c of CASES){const d=object(records[c.id]??{},'case');out.cases[c.id]={owner:text(d.owner??'','owner',200),procedure:text(d.procedure??'','procedure'),expected:text(d.expected??'','expected result')};}return out;}
function plan(workload,revision,input={},expectedTargetContext=''){const config=settings(input),contextsReady=!!config.sourceContext&&!!config.targetContext&&config.sourceContext!==config.targetContext&&(!expectedTargetContext||config.targetContext===expectedTargetContext);return {schemaVersion:1,kind:'ApplicationAcceptancePlan',planRevision:text(revision,'revision',200),workload:text(workload||'','workload',1000),sourceContext:config.sourceContext,targetContext:config.targetContext,expectedTargetContext,contextsReady,cases:CASES.map(c=>({...c,...config.cases[c.id],configured:!!config.cases[c.id].owner&&!!config.cases[c.id].procedure&&!!config.cases[c.id].expected})),gate:'Closed',productionReady:false,note:'Manual approved tests only. This app never runs these procedures, deploys workloads or authenticates evidence. Reported matches require independent review.'};}
function template(p){return {schemaVersion:1,kind:'ApplicationAcceptanceEvidence',planRevision:p.planRevision,workload:p.workload,results:p.cases.flatMap(c=>['source','target'].map(side=>({caseId:c.id,side,context:p[side+'Context'],status:'NotRun',observedAt:'',detail:'',evidenceRef:''})))};}
function evidence(p,input){object(input,'evidence');if(input.schemaVersion!==1||input.kind!=='ApplicationAcceptanceEvidence'||input.planRevision!==p.planRevision||input.workload!==p.workload)throw Error('Acceptance evidence does not match the current pilot and plan revision.');if(!p.workload||!p.contextsReady)throw Error('Choose a pilot and distinct source/target contexts matching the configured target preflight context before importing acceptance evidence.');if(!Array.isArray(input.results)||input.results.length>12)throw Error('Invalid acceptance result list.');const seen=new Set(),results=input.results.map(r=>{object(r,'result');const c=p.cases.find(c=>c.id===r.caseId);if(!c||!['source','target'].includes(r.side))throw Error('Unknown acceptance case or side.');const key=r.caseId+':'+r.side;if(seen.has(key))throw Error('Duplicate acceptance case and side.');seen.add(key);if(r.context!==p[r.side+'Context'])throw Error('Acceptance evidence uses a different context.');if(!['Pass','Fail','Error','NotRun'].includes(r.status))throw Error('Invalid acceptance outcome.');const record={caseId:c.id,side:r.side,context:r.context,status:r.status,observedAt:text(r.observedAt??'','observation timestamp',100),detail:text(r.detail??'','observation'),evidenceRef:text(r.evidenceRef??'','evidence reference',2000)};if(record.status!=='NotRun'&&(!record.detail||!record.evidenceRef||!/^\d{4}-\d{2}-\d{2}T.*(?:Z|[+-]\d{2}:\d{2})$/.test(record.observedAt)||!Number.isFinite(Date.parse(record.observedAt))))throw Error('Executed acceptance cases need a timestamp with timezone, observation and evidence reference.');if(record.status==='Pass'&&!c.configured)throw Error('Define the owner, procedure and measurable expected result before reporting a pass.');return record;});return {schemaVersion:1,kind:'ApplicationAcceptanceEvidence',planRevision:p.planRevision,workload:p.workload,results,note:'External historical records; no test was executed or authenticated by this app.'};}
function summary(p,record){const results=record?.planRevision===p.planRevision&&record?.workload===p.workload?record.results:[];const rows=p.cases.map(c=>{const source=results.find(r=>r.caseId===c.id&&r.side==='source'),target=results.find(r=>r.caseId===c.id&&r.side==='target'),complete=!!p.workload&&p.contextsReady&&c.configured&&source?.status==='Pass'&&target?.status==='Pass';return {...c,source:source||null,target:target||null,status:complete?'Reported source/target match':'Unresolved'};});const reportedComplete=rows.filter(r=>r.status==='Reported source/target match').length;return {gate:'Closed',productionReady:false,workload:p.workload,total:rows.length,reportedComplete,unresolved:rows.length-reportedComplete,rows,reason:'Owner-supplied outcomes and references are not independently verified. Coverage, security, data recovery and production authorization remain separate gates.'};}
function markdown(p,record){const s=summary(p,record);return '# Application acceptance workbook\n\nPilot: '+(p.workload||'Not selected')+'\nRevision: '+p.planRevision+'\nSource context: '+(p.sourceContext||'Not set')+'\nTarget context: '+(p.targetContext||'Not set')+'\nProduction gate: CLOSED\n\n'+s.rows.map(c=>'## '+c.title+'\nOwner: '+(c.owner||'Unassigned')+'\nProcedure:\n'+(c.procedure||'Not defined')+'\nExpected result:\n'+(c.expected||'Not defined')+'\n'+['source','target'].map(side=>side+': '+(c[side]?.status||'NotRun')+'\nObserved at: '+(c[side]?.observedAt||'Not recorded')+'\nEvidence: '+(c[side]?.evidenceRef||'Not supplied')+'\nObservation: '+(c[side]?.detail||'Not supplied')).join('\n')+'\n').join('\n')+'\n'+s.reason+'\n';}
root.MigrationAcceptance={CASES,settings,plan,template,evidence,summary,markdown};if(typeof module!=='undefined')module.exports=root.MigrationAcceptance;
})(typeof window!=='undefined'?window:globalThis);
